def restore_table(n, m, rows, cols):
    table = [[0 for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            table[i][j] = rows[i][j] if j < len(rows[i]) else cols[j][i]
    return table

