import sys

def solve():
    for line in sys.stdin:
        arr = list(map(int, line.split()))
        if len(arr) == 1:
            if arr[0] == 0:
                break
            else:
                res = ['YES']
                n = arr[0]
                a = list(map(int, sys.stdin.readline().split()))
                k = int(sys.stdin.readline())
                b = list(map(int, sys.stdin.readline().split()))
                i = 0
                j = 0
                while i < n:
                    if a[i] == b[j]:
                        i += 1
                        j += 1
                    else:
                        if i == 0 or a[i] > a[i - 1]:
                            res.append(str(i + 1) + ' R')
                        else:
                            res.append(str(i + 1) + ' L')
                        a[i] += a[i - 1]
                        a.pop(i - 1)
                        n -= 1
                print('\n'.join(res))
        else:
            continue

solve()

import math

def game(n):
    ans = 0
    sq = int(math.sqrt(n))
    for i in range(2, sq + 1):
        if n % i == 0:
            ans ^= 1
            while n % i == 0:
                n //= i
    if n > 1:
        ans ^= 1
    if ans == 0:
        return "Bob"
    return "Alice"

for _ in range(int(input())):
    n = int(input())
    print(game(n))

