def find_permutation(n, a, b):
    if a + b > n - 1 or abs(a - b) > 1:
        return "-1"
    perm = list(range(1, n + 1))
    if a >= b:
        for i in range(1, 2 * a, 2):
            perm[i], perm[i + 1] = perm[i + 1], perm[i]
    else:
        for i in range(0, 2 * b, 2):
            perm[i], perm[i + 1] = perm[i + 1], perm[i]
    return " ".join(map(str, perm))

