['import sys

def read_int():
    return int(sys.stdin.readline())

def read_line():
    return sys.stdin.readline().strip()

def read_tokens():
    return sys.stdin.readline().strip().split()

def solve():
    t = read_int()
    for _ in range(t):
        n = read_int()
        users = read_tokens()
        m = read_int()
        messages = []
        for _ in range(m):
            s, text = read_line().split(':')
            messages.append((s, text))

        # Check if it is possible to recover senders
        if not is_possible(messages):
            print("Impossible")
            continue

        # Recover senders
        senders = []
        for message in messages:
            if message[0] == '?':
                for user in users:
                    if user not in message[1] and user not in senders:
                        senders.append(user)
                        break
            else:
                senders.append(message[0])

        # Print the recovered messages
        for i in range(m):
            print("{}:{}".format(senders[i], messages[i][1]))

def is_possible(messages):
    # Check if there are two or more messages in a row with the same sender
    for i in range(1, len(messages)):
        if messages[i][0] == messages[i - 1][0]:
            return False

    # Check if a sender mention himself in his messages
    for message in messages:
        if message[0] in message[1]:
            return False

    return True

solve()
