    if next_dx == 0:
        next_angle = math.pi / 2 if next_dy > 0 else -math.pi / 2
    else:
        next_angle = math.atan(next_dy / next_dx)
        if next_dx < 0:
            next_angle += math.pi
    if abs(angle - next_angle) > math.pi / 2:
        danger += 1

