def max_beauty(n, k, books):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][1] = sum(books[:i])
    for j in range(2, k + 1):
        for i in range(j, n + 1):
            for x in range(j - 1, i):
                dp[i][j] = max(dp[i][j], dp[x][j - 1] & sum(books[x:i]))
    return dp[n][k]

print(max_beauty(n, k, books))

