        return 1
    if (i, j) in ways:
        return ways[(i, j)]

    ans = 0
    if i + 1 < h and (i + 1, j) not in black:
        ans += dfs(i + 1, j, ways)
    if j + 1 < w and (i, j + 1) not in black:
        ans += dfs(i, j + 1, ways)
    ways[(i, j)] = ans % mod
    return ways[(i, j)]

