import sys
class UnionFind:
    def __init__(self):
        self.par =[0]*200010
        self.siz =[0]*200010
        for i in range(200010):
            self.par[i]=i
    def find(self , u):
        if self.par[u] != u:
            self.par[u] = self.find(self.par[u])
        return self.par[u]
    def merge(self , a , b):
        ar = self.find(a)
        br = self.find(b)
        if ar != br:
            if self.siz[ar]<self.siz[br]:
                ar , br = br , ar
            self.par[br] = ar
            self.siz[ar] += self.siz[br]

