from fractions import Fraction
def binpow(x, n, mod):
    if n == 0: return 1
    if n == 1: return x % mod
    if n % 2 == 0:
        return binpow(x, n//2, mod)**2 % mod
    else:
        return x * binpow(x, n-1, mod) % mod

