a = list(map(int, input().strip().split()))
k = int(input().strip())
b = list(map(int, input().strip().split()))

result = find_possible_eating_order(n, a, k, b)
if result == "NO":
    print("NO")
else:
    print("YES")
    current_index = 1
    for action in result:
        print(f"{current_index} {action}")
        if action == 'L':
            current_index -= 1
        else:
            current_index += 1

