def dfs(u, p):
    visited[u] = True
    if len(adjList[u]) == 1 and u != 1:
        val[u] = 0
        return
    for v, w in adjList[u]:
        if v != p:
            dfs(v, u)
            if w == 0:
                val[u] = (val[u] or val[v])
            else:
                if val[u] == 0:
                    val[u] = val[v]
                elif val[v] == 0:
                    val[u] = 1
                else:
                    val[u] = 2

dfs(1, 1)
ans = 0

for i in range(1, n+1):
    if i == 1:
        continue
    if val[i] == 0:
        ans += n - 1
    elif val[i] == 1:
        ans += n - 2
    else:
        ans += n - 3

print(ans)

def check_obfuscation(s):
    used = set()
    i = 0
    a = 'a'
    while i < len(s):
        if s[i] not in used:
            used.add(s[i])
            j = i + 1
            while j < len(s):
                if s[j] == s[i]:
                    s = s[:j] + a + s[j + 1:]
                j += 1
            a = chr(ord(a) + 1)
        i += 1
    return s == a * len(used)

s = input()
print("YES" if check_obfuscation(s) else "NO")

