def vitalys_algorithm(s):
    while "yx" in s or "xy" in s:
        if "yx" in s:
            s = s.replace("yx", "xy", 1)
        else:
            s = s.replace("xy", "", 1)
    return s

s = input().strip()
print(vitalys_algorithm(s))

