    m, n = len(B), len(B[0])
    A = [['0' for _ in range(n)] for _ in range(m)]

    for i in range(m):
        for j in range(n):
            if B[i][j] == '1':
                A[i][j] = '1'
                for k in range(i):
                    A[k][j] = '1'
                for k in range(j):
                    A[i][k] = '1'

    return A

