MOD = 998244353

def mod_pow(base, exponent, modulus):
    result = 1
    base = base % modulus
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulus
        exponent = exponent >> 1
        base = (base * base) % modulus
    return result

def solve(n, m, L, R):
    total_cells = n * m
    total_numbers = R - L + 1
    if total_cells % 2 == 1:
        return mod_pow(total_numbers, total_cells, MOD)
    else:
        even_numbers = (total_numbers + 1) // 2
        odd_numbers = total_numbers // 2
        even_config = mod_pow(even_numbers + odd_numbers, total_cells, MOD)
        odd_config = mod_pow(even_numbers - odd_numbers, total_cells, MOD)
        return (even_config + odd_config) * pow(2, MOD - 2, MOD) % MOD

n, m, L, R = map(int, input().split())
print(solve(n, m, L, R))

MOD = 10**9 + 7

def char_to_int(c):
    if '0' <= c <= '9':
        return ord(c) - ord('0')
    if 'A' <= c <= 'Z':
        return ord(c) - ord('A') + 10
    if 'a' <= c <= 'z':
        return ord(c) - ord('a') + 36
    if c == '-':
        return 62
    if c == '_':
        return 63

def count_bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def solve(s):
    bit_counts = [0] * 64
    for c in s:
        bit_counts[char_to_int(c)] += 1

    result = 1
    for c in s:
        total = 0
        target = char_to_int(c)
        for i in range(64):
            if i & target == target:
                total += bit_counts[i]
        result = (result * total) % MOD
    return result

s = input().strip()
print(solve(s))

