        roads.append((c, a, b))
    roads.sort()
    ans1, ans2 = 0, 0
    for cost, a, b in roads:
        if find(a) != find(b):
            union(a, b)
            ans1 += cost
            ans2 += cost
    for cost, a, b in roads:
        if find(a) != find(b):
            ans1 -= cost
            break
    print(ans1, ans2)
