    graph=[[] for i in range(n+1)]
    indeg=[0]*(n+1)
    for i in range(m):
        a,b=map(int,input().split())
        graph[a].append(b)
        indeg[b]+=1
    q=deque([i for i in range(1,n+1) if indeg[i]==0])
