def solve(l):
  if '*'in l:
    return max(solve(l[:i]) * solve(l[i+1:]) 
      for i in filter(lambda i: l[i] == '*', range(1,len(l)-1)))

  else:
    return reduce((lambda x,y: x+y if y!='*' else x*y), l)
