import sys

def dfs(vert: int, p: int, e: int, d: List[int], gr: dict, used: set, ans: list) -> bool:
    used.add(vert)
    ans.append(e)
    for v in gr[vert]:
        if v == p:
            continue
        if v in used:
            if (d[vert] + d[v]) % 2 != (e % 2):
                return False
            continue
        if dfs(v, vert, e + 1, d, gr, used, ans):
            return True
        ans.pop()
    return False

