import math
from collections import deque

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])

    if val == 0:
        return 0
    elif val > 0:
        return 1
    else:
        return -1

def onSegment(p, q, r):
    if (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
        q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1])):
        return True
    return False

def doIntersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)
    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)

    if (o1 != o2 and o3 != o4):
        return True

    if (o1 == 0 and onSegment(p1, p2, q1)):
        return True

    if (o2 == 0 and onSegment(p1, q2, q1)):
        return True

    if (o3 == 0 and onSegment(p2, p1, q2)):
        return True

    if (o4 == 0 and onSegment(p2, q1, q2)):
        return True

    return False

class Block:
    def __init__(self, p1, p2, p3, p4):
        self.p1 = p1
        self.p2 = p2
        self.p3 = p3
        self.p4 = p4

class Graph:
    def __init__(self, V):
        self.V = V
        self.adj = [[] for i in range(V)]

    def addEdge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

    def BFS(self, s, d):
        visited = [False] * self.V
        queue = deque()

        queue.append(s)
        visited[s] = True

        while queue:
            s = queue.popleft()

            if s == d:
                return True

            for i in self.adj[s]:
                if visited[i] == False:
                    queue.append(i)
                    visited[i] = True

        return False

def isInside(point, polygon):
    n = len(polygon)

    if n < 3:
        return False

    extreme = (100000000, point[1])

    count = 0
    i = 0

    while True:
        next = (i + 1) % n

        if doIntersect(point, extreme, polygon[i], polygon[next]):
            if orientation(polygon[i], point, polygon[next]) == 0:
                return onSegment(polygon[i], point, polygon[next])
            count += 1
        i = next

        if i == 0:
            break

    if count % 2 == 1:
        return True

    return False

def createGraph(blocks, n, roads):
    graph = Graph(n + 1)

    for i in range(n):
        for j in range(i + 1, n):
            if isInside([0, 0], [blocks[i].p1, blocks[i].p2, blocks[i].p3, blocks[i].p4]) and isInside([0, 0], [blocks[j].p1, blocks[j].p2, blocks[j].p3, blocks[j].p4]):
                graph.addEdge(i, j)

    for i in range(n):
        for road in roads:
            a, b, c = road
            den = (a * blocks[i].p1[0] + b * blocks[i].p1[1] + c)
            if den == 0:
                continue

            x = (-c - b * blocks[i].p1[1]) / a
            y = (-c - a * blocks[i].p1[0]) / b

            if isInside([x, y], [blocks[i].p1, blocks[i].p2, blocks[i].p3, blocks[i].p4]):
                graph.addEdge(i, n)

    return graph


