import sys

def check(p, l, r):
    lm = p[l]
    for i in range(l, r):
        lm = min(lm, p[i])
    rm = p[r]
    for i in range(r + 1, len(p)):
        rm = max(rm, p[i])
    return lm == p[l] and rm == p[r]

