from collections import deque

def is_valid(g):
    open = 0
    for c in g:
        if c in '{[(': open += 1
        elif c in ')}]': open -= 1
        if open < 0: return False
    return open == 0

def get_vars(g):
    ans = []
    for c in g:
        if c in '0123456789': ans += [int(c)]
    return ans

def simulate(g, vars):
    p = deque()
    for var in vars: p.append(var)
    cur = 0
    i = 0
    while i < len(g):
        c = g[i]
        if c in '{[(':
            p.append(cur)
            cur = 0
        elif c in ')}]':
            cur = p.pop()
        elif c == '+':
            cur += p.pop()
        elif c == '-':
            cur -= p.pop()
        elif c == '*':
            cur *= p.pop()
        elif c == '/':
            cur //= p.pop()
        elif c == '>':
            p.append(cur)
        elif c == '<':
            cur = p.pop()
        i += 1
    return cur

def solve(g):
    all_vars = get_vars(g)
    for vars in all_vars:
        if simulate(g, vars) == 0:
            return ''.join(map(str, vars))
    return "false"

g = input()
if not is_valid(g):
    print('false')
else:
    print(solve(g))

from collections import defaultdict, deque

def solve(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    visited = [False] * n
    group = [-1] * n

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        group[start] = 1
        while queue:
            v = queue.popleft()
            for u in graph[v]:
                if not visited[u]:
                    visited[u] = True
                    group[u] = 3 - group[v]
                    queue.append(u)
                elif group[u] == group[v]:
                    return False
        return True

    for i in range(n):
        if not visited[i]:
            if not bfs(i):
                print(-1)
                return

    vertex_set = defaultdict(set)
    for i, g in enumerate(group):
        vertex_set[g].add(i)

    if len(vertex_set) != 2:
        print(-1)
        return

    v1, v2 = list(vertex_set.keys())

    for i in range(n):
        if group[i] == v1:
            print(1, end=' ')
        elif group[i] == v2:
            print(2, end=' ')
        else:
            print(3, end=' ')
    print()

n, m = map(int, input().split())
edges = [list(map(int, input().split())) for _ in range(m)]
solve(n, m, edges)

