        d1 = norm(v1)
        mv = v1
        mv[0], mv[1] = -mv[1], mv[0]
        mv = [mv[0]/d1, mv[1]/d1]
        ok = True
        for k in range(n):
            x3, y3 = l[k]
            d = abs(cross(v1, [x3-x1, y3-y1])/d1)
            if d < EPS:
