import sys

mod = 10 ** 9 + 7
fact = [1 for i in range(72)]

for i in range(2, 72):
  fact[i] = (fact[i - 1] * i) % mod

def power(x, y):
  if y == 0:
    return 1
  elif y == 1:
    return x
  elif y % 2 == 0:
    return power((x ** 2) % mod, y // 2)
  else:
    return (x * power(x, y - 1)) % mod

n = int(sys.stdin.readline())
arr = [int(x) for x in sys.stdin.readline().split()]

count = [0 for i in range(72)]
for x in arr:
  count[x] += 1

ans = 0
for i in range(1, 72):
  if count[i] > 0:
    ans = (ans + (fact[count[i] + count[i % 35]] * power((fact[count[i]] * fact[count[i % 35]]) % mod, mod - 2)) % mod)

print(ans)

def can_assign_sender(users, messages, last_sender, index):
    if index == len(messages):
        return True
    if messages[index][0] != '?':
        if messages[index][0] == last_sender or any(user in messages[index][1] for user in users):
            return False
        return can_assign_sender(users, messages, messages[index][0], index + 1)
    for user in users:
        if user != last_sender and not any(user in msg for msg in messages[index][1]):
            messages[index][0] = user
            if can_assign_sender(users, messages, user, index + 1):
                return True
            messages[index][0] = '?'
    return False

