def mod_pow(base, pwr, mod):
    if pwr == 0:
        return 1
    if pwr == 1:
        return base
    val = mod_pow(base, int(pwr / 2), mod)
    val = (val * val) % mod
    if pwr % 2 != 0:
        val = (val * base) % mod
    return val % mod


