combination = ('RGB', 'RBG', 'GRB', 'GBR', 'BGR', 'BRG')
summa = [0, 0, 0, 0, 0, 0]

def diff(input, pattern):
	count = 0
	if len(input) == 1:
		if input[0] != pattern[0]:
			count += 1
		return count
	elif len(input) == 2:
		if input[0] != pattern[0]:
			count += 1
		if input[1] != pattern[1]:
			count += 1
		return count
	else:
		if input[0] != pattern[0]:
			count += 1
