def func(n: int, arr: list, count: list):
	if n < 3:
		return '\n'.join([''.join(i) for i in arr])
	for i in range(n):
		for j in range(n):
			if arr[i][j] == 'X':
				count[(i + j) % 3] += 1
	what = count.index(min(count))
	min_mod = what
	for i in range(n):
		for j in range(n):
			if (i + j) % 3 == min_mod and arr[i][j] == 'X':
				arr[i][j] = 'O'
	return '\n'.join([''.join(i) for i in arr])

