import os, sys
from io import BytesIO, IOBase

def cons(n, x):
	xx = n.bit_length()
	dp = [[10 ** 10] * n for _ in range(xx)]
	dp[0] = x
	for i in range(1, xx):
		for j in range(n - (1 << i) + 1):
			dp[i][j] = min(dp[i - 1][j], dp[i - 1][j + (1 << i - 1)])
	return dp

def cons1(n, x):
	xx = n.bit_length()
	dp = [[-10 ** 10] * n for _ in range(xx)]
	dp[0] = x
	for i in range(1, xx):
		for j in range(n - (1 << i) + 1):
			dp[i][j] = max(dp[i - 1][j], dp[i - 1][j + (1 << i - 1)])
	return dp

def ask(l, r, dp):
	xx1 = (r - l + 1).bit_length() - 1
	return min(dp[xx1][l], dp[xx1][r - (1 << xx1) + 1])

def ask1(l, r, dp):
	xx1 = (r - l + 1).bit_length() - 1
	return max(dp[xx1][l], dp[xx1][r - (1 << xx1) + 1])

def main():
	for _ in range(int(input())):
		(n, m) = map(int, input().split())
		s = input().strip()
		arr = [0]
		for i in range(n):
			arr.append(arr[-1] + (-1 if s[i] == '-' else 1))
		n += 1
		mini = cons(n, arr)
		maxi = cons1(n, arr)
		for _ in range(m):
			(l, r) = map(int, input().split())
			(q, w) = (ask(0, l - 1, mini), ask1(0, l - 1, maxi))
			if r == n - 1:
				print(w - q + 1)
			else:
				dec = arr[r] - arr[l - 1]
				(q1, w1) = (ask(r + 1, n - 1, mini) - dec, ask1(r + 1, n - 1, maxi) - dec)
				if min(w, w1) < max(q, q1):
					print(w1 - q1 + w - q + 2)
				else:
					print(max(w, w1) - min(q, q1) + 1)
