def seive():
	nn = 1000100
	vis = [False] * nn
	for i in range(4, nn, 2):
		vis[i] = True
	i = 3
	(vis[0], vis[1]) = (True, True)
	while i * i < nn:
		if not vis[i]:
			j = i * i
			while j < nn:
				vis[j] = True
				j += 2 * i
		i += 2
	for i in range(nn):
		if not vis[i]:
			primes.append(i)
