def find_factors(nn):
	ans = []
	for i in primes:
		if nn % i == 0:
			count = 0
			while nn % i == 0:
				count += 1
				nn /= i
			ans.append((i, count))
	if nn > 1:
		ans.append((nn, 1))
	return ans
