def recursive_dfs(graph, start, path=[]):
	path = path + [start]
	for node in graph[start]:
		if not node in path:
			path = recursive_dfs(graph, node, path)
	return path

def conn(x, y):
	(a, b) = (x[0], x[1])
	(c, d) = (y[0], y[1])
	return c < a < d or c < b < d
