def solve(x, m, d, mod, par):
	dp = [[array('i', [0]) * m for _ in range(2)] for _ in range(len(x))]
	zz = int(x[0])
	for _ in range(1, zz):
		if _ == d:
			continue
		dp[0][0][_ % m] += 1
	if zz != d:
		dp[0][1][zz % m] = 1
	for i in range(1, len(x)):
		zz = int(x[i])
		if i & 1:
			for j in range(m):
				z = (j * 10 + d) % m
				dp[i][0][z] = (dp[i][0][z] + dp[i - 1][0][j] + (0 if d >= zz else dp[i - 1][1][j])) % mod
				dp[i][1][z] = (dp[i][1][z] + (0 if d != zz else dp[i - 1][1][j])) % mod
		else:
			for j in range(m):
				for k in range(10):
					if k == d:
						continue
					z = (j * 10 + k) % m
					dp[i][0][z] = (dp[i][0][z] + dp[i - 1][0][j] + (0 if k >= zz else dp[i - 1][1][j])) % mod
					dp[i][1][z] = (dp[i][1][z] + (0 if k != zz else dp[i - 1][1][j])) % mod
	if par:
		return (dp[len(x) - 1][0][0] + dp[len(x) - 1][1][0]) % mod
	return dp[len(x) - 1][0][0]

