def gcd(a1, a2):
	if a2 == 0:
		return a1
	else:
		return gcd(a2, a1 % a2)

def egcd(a, b):
	if a == 0:
		return (b, 0, 1)
	else:
		(g, x, y) = egcd(b % a, a)
		return (g, y - b // a * x, x)
