def exd_gcd(a, b):
	if a % b == 0:
		return (0, 1 if b > 0 else -1)
	(x, y) = exd_gcd(b, a % b)
	return (y, x - a // b * y)

def interval_intersect(a, b, c, d):
	if b <= a or d <= c:
		return 0
	if c < a:
		(a, b, c, d) = (c, d, a, b)
	if c < b:
		return min(b, d) - c
	else:
		return 0

