def calculate(array):
	n = len(array)
	finalarray = []
	finalarray.append(array)
	finalarray.append([])
	while n != 1:
		for x in range(n - 1):
			finalarray[-1].append(finalarray[-2][x] ^ finalarray[-2][x + 1])
		finalarray.append([])
		n -= 1
	return finalarray

