class UnionFindAlgo:

	def __init__(self, n):
		self.par = [i for i in range(n)]

	def find(self, node):
		if self.par[node] == node:
			return node
		self.par[node] = self.find(self.par[node])
		return self.par[node]

	def union(self, u, v):
		a = self.find(u)
		b = self.find(v)
		if a == b:
			return
		self.par[b] = a
