MOD = 10 ** 9 + 7

def solve():
	(M, N) = getInts()
	ans = 0
	for x in range(1, M + 1):
		tmp = pow(x / M, N) * (1 - pow((x - 1) / x, N)) / (1 - (x - 1) / x)
		ans += tmp
	return ans
