from collections import UserDict

class Tree(UserDict):

	def __init__(self, g):
		super().__init__()
		for (name, value) in enumerate(g, 1):
			self[value] = name

	def __setitem__(self, name, value):
		if name in self:
			if value is not None:
				self[name].add(value)
				self[value] = None
		elif value is None:
			super().__setitem__(name, set())
		else:
			super().__setitem__(name, {value})
			self[value] = None
