def dfs(v):
	stack = [v]
	visited = set()
	while stack:
		v = stack.pop()
		if v not in visited:
			visited.add(v)
			stack.append(v)
			stack.extend(tree[v])
		else:
			t[v] = (1, colors[v])
			for u in tree[v]:
				t[v] = ((t[v][0] * t[u][1] + t[v][0] * t[u][0] * (not colors[u])) % (10 ** 9 + 7), (t[v][1] * t[u][1] + t[v][0] * t[u][1] * (not colors[v]) + t[v][1] * t[u][0] * (not colors[u])) % (10 ** 9 + 7))
