from sys import stdin
from math import gcd

def lcm(a, b):
	return a * b // gcd(a, b)

def exgcd(a, b) -> (int, int, int):
	if b == 0:
		return (a, 1, 0)
	(d, x, y) = exgcd(b, a % b)
	t = x
	x = y
	y = t - a // b * y
	return (d, x, y)

def cal(v: list) -> int:
	now = v[0]
	for i in range(1, len(v)):
		a = now[0]
		b = -v[i][0]
		c = v[i][1] - now[1]
		(g, x, y) = exgcd(a, b)
		x *= c // g
		y *= c // g
		lc = lcm(a, b)
		now = (lc, (a * x + now[1]) % lc)
	return now[1]

