from math import ceil

def count_xy(n, b):
	c = {abs(b[i + 1] - b[i]) for i in range(n - 1) if abs(b[i + 1] - b[i]) != 1}
	if 0 in c:
		return (-1, -1)
	if len(c) > 1:
		return (-1, -1)
	if len(c) == 0:
		return (1, max(b))
	y = c.pop()
	for i in range(1, n):
		(cur, pr) = (b[i], b[i - 1])
		if abs(cur - pr) == 1 and min(cur, pr) % y == 0:
			return (-1, -1)
	return (ceil(max(b) / y), y)
