def solve(n, p, a):
	fathers = [i for i in range(n)]

	def getparent(a):
		if fathers[a] == a:
			return a
		father = getparent(fathers[a])
		fathers[a] = father
		return father

	def sameset(a, b):
		return getparent(a) == getparent(b)

	def uniset(a, b):
		fathers[a] = b
	paths = []
	for i in range(n):
		if a[i] < p:
			for bi in range(i - 1, 0, -1):
				if a[bi] % a[i] != 0:
					break
				if a[bi] < a[i]:
					break
				else:
					paths.append((bi, i, a[i]))
			for bi in range(i + 1, n, +1):
				if a[bi] % a[i] != 0:
					break
				if a[bi] < a[i]:
					break
				else:
					paths.append((bi, i, a[i]))
	paths.sort()
	sorted_paths = paths
	u = 0
	we = 0
	found = 0
	for i in range(n - 1):
		if u >= len(sorted_paths):
			break
		while True:
			if u >= len(sorted_paths):
				break
			current_path = sorted_paths[u]
			if not sameset(current_path[0], current_path[1]):
				uniset(current_path[0], current_path[1])
				we += current_path[2]
				found += 1
				u += 1
				break
			u += 1
	we += p * (n - found - 1)
	return we

def readlinesasint(n: int, file):
	buffer = []
	nums = []
	for i in range(n):
		char = file.read(1)
		while char not in '\r\n\t ':
			buffer.append(char)
			char = file.read(1)
		nums.append(int(''.join(buffer)))
		buffer = []
	return nums

def new_solve(n, p, a):
	sorted_a = sorted(enumerate(a), key=lambda x: x[1])
	is_connected_to_neighbour = [False for i in range(n - 1)]
	ret_val = 0
	for (index, value) in sorted_a:
		if value >= p:
			break
		i = index - 1
		while i >= 0:
			if a[i] % a[index] == 0:
				if is_connected_to_neighbour[i]:
					i -= 1
					break
					continue
				else:
					is_connected_to_neighbour[i] = True
					ret_val += a[index]
			else:
				break
			i -= 1
		i = index + 1
		while i < n:
			if a[i] % a[index] == 0:
				if is_connected_to_neighbour[i - 1]:
					i += 1
					break
					continue
				else:
					is_connected_to_neighbour[i - 1] = True
					ret_val += a[index]
			else:
				break
			i += 1
	for i in range(len(is_connected_to_neighbour)):
		if not is_connected_to_neighbour[i]:
			ret_val += p
	return ret_val
