def ub(arr, lo, hi, val):
	while lo < hi:
		mid = (lo + hi) // 2
		if arr[mid] > val:
			hi = mid - 1
		elif arr[mid] <= val:
			lo = mid + 1
	if lo == len(arr) - 1 and arr[-1] <= val:
		lo = len(arr)
	return lo

def lb(arr, lo, hi, val):
	while lo < hi:
		mid = (lo + hi) // 2
		if arr[mid] < val:
			lo = mid + 1
		elif arr[mid] >= val:
			hi = mid - 1
	if lo == len(arr) - 1 and arr[-1] < val:
		lo = len(arr)
	return lo
