			nt.append(i)
	nt.sort(reverse=True)
	bad.sort(reverse=True)
	ans = len(bad)
	for val in bad:
		id = None
		for i in range(len(nt)):
			if val % (val - nt[i]) == nt[i]:
				id = i
				break
		if id == None:
			return -1
		nt.pop(id)
	return ans
