import math

def lcm(a, b):
	return a * b // math.gcd(a, b)

def egcd(a, b):
	if b == 0:
		return (a, 1, 0)
	(g, x, y) = egcd(b, a % b)
	return (g, y, x - a // b * y)

def crt(a, m1, b, m2):
	(g, x, y) = egcd(m1, m2)
	if (b - a) % g != 0:
		return (0, -1)
	m = m1 * m2 // g
	r = (b - a) // g * x % (m2 // g)
	r = (a + m1 * r) % m
	return (r, m)

