def find_right(node):
	global l, r, s, n
	while n:
		r += 1
		n -= 1
		if s[r] == '(':
			node[2].append([r, -1, []])
			find_right(node[2][-1])
		else:
			node[1] = r
			return True
	return False

def find_left(node):
	global l, r, s, n
	while n:
		l -= 1
		n -= 1
		if s[l] == ')':
			node[2].append([-1, l, []])
			find_left(node[2][-1])
		else:
			node[0] = l
			return True
	return False
