def get_print_int(x):
	sys.stdout.write(str(x) + '\n')

def get_print(x):
	sys.stdout.write(x + '\n')

def solve():
	for _ in range(get_int()):
		(n, k) = get_ints()
		a = get_string()
		b = get_string()
		(temp1, temp2) = ([0] * 26, [0] * 26)
		for i in a:
			temp1[ord(i) - 97] += 1
		for i in b:
			temp2[ord(i) - 97] += 1
		f = 0
		count = 0
		for i in range(26):
			d = temp1[i] - temp2[i]
			if d == 0:
				continue
			if abs(d) % k == 1:
				f = 1
				break
			count += d // k
			if count < 0:
				f = 1
				break
		if f:
			get_print('No')
		else:
			get_print('Yes')
solve()

