def constructK2(v, k):
	res = set()
	for i in range(1, k):
		res.add((v[0], v[i]))
	for i in range(1, k):
		for j in range(1, k):
			if i != j:
				res.add((min(v[i], v[j]), max(v[i], v[j])))
	for i in range(2, k, 2):
		v1 = i
		v2 = i + 1
		if v2 >= k:
			v2 = 1
		res.remove((min(v[v1], v[v2]), max(v[v1], v[v2])))
	for i in range(1, k):
		res.add((v[i], v[k]))
		res.add((v[i], v[k + 1]))
	res.add((v[k], v[k + 1]))
	return res

def construct(k):
	res1 = constructK2([x for x in range(1, k + 3)], k)
	res2 = constructK2([x + k + 2 for x in range(1, k + 3)], k)
	return res1 | res2 | {(1, k + 3)}

