def solve():
	n = int_input()
	a = ints_input()
	if sum(a) % 2 == 1:
		print('NO')
		return
	reversed = False
	ops = []

	def do_op(i):
		ops.append(i + 1)
		a[i] = a[i + 1] = a[i + 2] = a[i] ^ a[i + 1] ^ a[i + 2]
	if a[0] == 1:
		i = 1
		found = False
		while i + 1 < n:
			if a[i] == a[i + 1]:
				i += 2
			else:
				found = True
				break
		if not found:
			if i == n - 1 and a[i] == 1:
				print('NO')
				return
			else:
				reversed = True
				a = a[::-1]
				if a[0] == 1:
					do_op(0)
		else:
			x = i
			while x >= 1:
				do_op(x - 1)
				x -= 2
	p = 1
	while p + 1 < n:
		if a[p] != a[p + 1]:
			do_op(p)
			if a[p] == 0:
				p += 2
		else:
			if a[p] != 0:
				do_op(p - 1)
			p += 2
	print('YES')
	print(len(ops))
	if reversed:
		ops = [n - 1 - i for i in ops]
	print(' '.join([str(x) for x in ops]))
if True:
	for _ in range(int_input()):
		solve()
else:
	solve()

