def mkt():
	C[0][0] = 1
	for i in range(1, MX_BIT):
		for j in range(i + 1):
			C[i][j] = C[i - 1][j] + (C[i - 1][j - 1] if j else 0)

def solve(x, k):
	a = 0
	for i in reversed(range(MX_BIT)):
		if ck(x, i) != 0:
			a += C[i][k]
			k -= 1
		if k == 0:
			break
	return a
