def getmid(arr, l1, flag):
	(low, high) = (1, n)
	if l1 % 2 == 0 and flag:
		midv = l1 // 2
	else:
		midv = l1 // 2 + 1
	while low <= high:
		mid = (low + high) // 2
		ret = sum(arr, mid)
		if ret >= midv:
			high = mid - 1
		else:
			low = mid + 1
	return low
