import sys

class Main:

	def __init__(self):
		self.buff = None
		self.index = 0

	def next(self):
		if self.buff is None or self.index == len(self.buff):
			self.buff = self.next_line()
			self.index = 0
		val = self.buff[self.index]
		self.index += 1
		return val

	def next_line(self):
		return sys.stdin.readline().split()

	def next_ints(self):
		return [int(x) for x in sys.stdin.readline().split()]

	def next_int(self):
		return int(self.next())

	def solve(self):
		(n, x, y) = self.next_ints()
		xx = self.next()
		stp = 0
		for i in range(0, x):
			if i == y:
				if xx[-1 - i] != '1':
					stp += 1
			elif xx[-1 - i] != '0':
				stp += 1
		print(stp)
Main().solve()

