def answer(n, q):
	p = []
	dic = {}
	for i in range(1, n + 1):
		dic[i] = []
	for li in q:
		dic[li[0]].append(li)
		dic[li[1]].append(li)
		dic[li[2]].append(li)
	one = []
	two = []
	for i in range(1, n + 1):
		if len(dic[i]) == 1:
			one.append(i)
		elif len(dic[i]) == 2:
			two.append(i)
	a = one[0]
	b = 0
	c = 0
	for i in two:
		for li in dic[i]:
			if a in li:
				b = i
				c = sum(li) - (a + b)
				break
	p = p + [a, b, c]
	for _ in range(n - 3):
		for li in dic[b]:
			if (a in li) is False and (b in li and c in li):
				a = b
				b = c
				c = sum(li) - (a + b)
				p.append(c)
	return ' '.join([str(c) for c in p])
