def check_seq(n, a):
	d = a[1][0] - a[0][0]
	(found, ind, prev) = (False, a[0][1], a[1][0])
	for i in range(2, n):
		if abs(a[i][0] - prev - d) > 0.1:
			if found:
				return (False, -1)
			found = True
			ind = a[i][1]
			continue
		prev = a[i][0]
	return (True, ind)

