import os, sys
from io import BytesIO, IOBase

def topsort(n, path):
	(ans, poi, visi) = ([], [0] * n, [0] * n)
	for i in range(n):
		if visi[i]:
			continue
		visi[i] = 2
		(st, st1) = ([i], [])
		while len(st):
			x = st[-1]
			if poi[x] == len(path[x]):
				visi[x] = 1
				st1.append(st.pop())
			else:
				i = path[x][poi[x]]
				poi[x] += 1
				if visi[i] == 2:
					return -1
				if not visi[i]:
					st.append(i)
					visi[i] = 2
		ans += st1
	return ans[::-1]

