def slide_min(tl, ql, val):
	res = [0] * (tl - ql + 1)
	q = [0] * tl
	s = 0
	t = 0
	for i in range(0, tl):
		while s < t and val[q[t - 1]] >= val[i]:
			t -= 1
		q[t] = i
		t += 1
		if i - ql + 1 >= 0:
			res[i - ql + 1] = val[q[s]]
			if q[s] == i - ql + 1:
				s += 1
	return res

def slide_min2(tl, ql, val):
	res = 0
	q = [0] * tl
	s = 0
	t = 0
	for i in range(0, tl):
		while s < t and val[q[t - 1]] >= val[i]:
			t -= 1
		q[t] = i
		t += 1
		if i - ql + 1 >= 0:
			res += val[q[s]]
			if q[s] == i - ql + 1:
				s += 1
	return res
