def check(n, p):
	stack = []
	next = 1
	used = [False for i in range(n + 1)]
	pos = 0
	while next != n + 1:
		if not used[next]:
			stack.append(p[pos])
			used[p[pos]] = True
			pos += 1
		elif not stack:
			return False
		elif stack[-1] != next:
			return False
		else:
			stack.pop()
			next += 1
	return True

def solve(n, k, P):
	p = [(P[i], i) for i in range(k)]
	p.sort()
	comp = [0 for i in range(k)]
	for i in range(k):
		(L, idx) = p[i]
		comp[idx] = i + 1
	if not check(k, comp):
		return [-1]
	p = p[::-1]
	R = n
	ans = []
	pre = -1
	flag = False
	for i in range(k):
		if not flag:
			(L, idx) = p[i]
			if L == R:
				if idx < pre:
					R = L
					break
				pre = idx
				R -= 1
				continue
			L += 1
			ans += [j for j in range(L, R + 1)]
			if idx < pre:
				R = p[i][0]
				break
			pre = idx
			R = L - 2
	else:
		ans += [j for j in range(1, R + 1)]
		ans = P + ans[::-1]
		return ans
	rest = [P[i] for i in range(pre) if P[i] <= R]
	if len(rest) != R:
		return [-1]
	elif not check(R, rest):
		return [-1]
	else:
		R = 0
	ans = P + ans[::-1]
	return ans
