ans = 0

def xorchecker(l, ans, pow_):
	if pow_ == -1:
		return ans
	one = []
	zero = []
	for i in l:
		if i & 1 << pow_ != 0:
			one.append(i)
		else:
			zero.append(i)
	if zero == [] or one == []:
		return xorchecker(l, ans, pow_ - 1)
	else:
		return min(xorchecker(zero, ans + (1 << pow_), pow_ - 1), xorchecker(one, ans + (1 << pow_), pow_ - 1))
