def rad_len(a, h, c):
	x = c * a / 2
	y = c * h
	return sqrt((x - a / 2) ** 2 + (y - 0) ** 2)

def get_max_radius(a, h):
	lo = 0.0
	hi = 1.0
	while abs(lo - hi) > 1e-09:
		p = lo + (hi - lo) / 3
		q = lo + 2 * (hi - lo) / 3
		if rad_len(a, h, p) > rad_len(a, h, q):
			lo = p
		else:
			hi = q
	return rad_len(a, h, lo)
