def dfs_1(v):
	q = [v, 0]
	while len(q) != 0:
		i = q.pop()
		v = q.pop()
		if i == 0:
			color[v] = 1
		if i == len(g[v]):
			color[v] = 2
			continue
		q.append(v)
		q.append(i + 1)
		w = g[v][i]
		if color[w] == 0:
			q.append(w)
			q.append(0)
		elif color[w] == 1:
			in_cycles.append(w)
		elif color[w] == 2:
			more_than_one.append(w)

def dfs_2(v):
	q = [v, 0]
	while len(q) != 0:
		i = q.pop()
		v = q.pop()
		if i == 0:
			color_tmp[v] = 1
		if i == len(g[v]):
			color_tmp[v] = 2
			continue
		q.append(v)
		q.append(i + 1)
		w = g[v][i]
		if color_tmp[w] == 0:
			q.append(w)
			q.append(0)

def fill_not_accessible(color, answer):
	for (i, c) in enumerate(color):
		if c == 0:
			answer[i] = 0

def fill_more_than_one(color, answer):
	for (i, c) in enumerate(color):
		if c == 2:
			answer[i] = 2

def fill_inf(color, answer):
	for (i, c) in enumerate(color):
		if c == 2:
			answer[i] = -1
