def convert(diff, k):
	(lena, lenb) = (0, 0)
	for letter in sorted(diff.keys()):
		n_letters = diff[letter]
		if n_letters > 0:
			lenb += n_letters
		else:
			lena += abs(n_letters)
		if lena < lenb:
			return 'NO'
	for (key, val) in diff.items():
		if abs(val) % k != 0:
			return 'NO'
	return 'YES'
