from types import GeneratorType

def recursive(f, stack=[]):

	def wrappedfunc(*args, **kwargs):
		if stack:
			return f(*args, **kwargs)
		else:
			to = f(*args, **kwargs)
			while True:
				if type(to) is GeneratorType:
					stack.append(to)
					to = next(to)
				else:
					stack.pop()
					if not stack:
						break
					to = stack[-1].send(to)
			return to
	return wrappedfunc
gr = []
childs = []
n = 0

@recursive
def dfs(node, par):
	global gr, cost, n, childs
	su = 1
	for i in gr[node]:
		if i != par:
			yield dfs(i, node)
			su += childs[i]
			cost.append(childs[i] * (n - childs[i]))
	childs[node] = su
	yield
