def solve(N, C):
	A = []
	for c in C:
		if not A or A[-1] != c:
			A.append(c)
	colors = list(set(C))
	colors.sort()
	cmap = {c: i + 1 for (i, c) in enumerate(colors)}
	A = [cmap[a] for a in A]
	N = len(A)
	C = len(colors)
	dp = [[[float('inf') for _ in range(2)] for _ in range(N + 1)] for _ in range(N + 1)]
	for i in range(N):
		dp[i][i][0] = 0
		dp[i][i][1] = 0
	for r in range(N):
		for l in range(r, -1, -1):
			for i in range(2):
				c = A[l] if i == 0 else A[r]
				if l:
					dp[l - 1][r][0] = min(dp[l - 1][r][0], dp[l][r][i] + (1 if c != A[l - 1] else 0))
				if r + 1 < N:
					dp[l][r + 1][1] = min(dp[l][r + 1][1], dp[l][r][i] + (1 if c != A[r + 1] else 0))
	print(min(dp[0][N - 1]))

def solve2(N, C):
	A = []
	for c in C:
		if not A or A[-1] != c:
			A.append(c)
	B = A[::-1]
	N = len(A)
	dp = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
	for i in range(1, N + 1):
		for j in range(1, N + 1):
			dp[i][j] = dp[i - 1][j - 1] + 1 if A[i - 1] == B[j - 1] else max(dp[i - 1][j], dp[i][j - 1])
	print(N - 1 - dp[N][N] // 2)
