def main():
	n = int(input())
	a = list(map(int, input().split()))
	su = sum(a)
	if su == 1:
		return -1
	fac = []
	if not su % 2:
		fac.append(2)
	while not su % 2:
		su //= 2
	for i in range(3, int(su ** 0.5) + 1, 2):
		if not su % i:
			fac.append(i)
		while not su % i:
			su //= i
	if su != 1:
		fac.append(su)
	ans = 10 ** 20
	for i in fac:
		(ans1, car) = (0, 0)
		for j in range(n - 1):
			if a[j] + car < 0:
				x = abs(a[j] + car)
				ans1 += x
				car = -x
				continue
			be = (a[j] + car) % i
			ab = i - be
			if ab < be:
				car = -ab
				ans1 += ab
			else:
				car = be
				ans1 += be
		if a[-1] + car < 0:
			ans1 += abs(a[-1] + car)
		ans = min(ans, ans1)
	return ans
