inf = 1 << 64

def slv():
	_ = input()
	(n, K) = map(int, input().split())
	mines = [tuple(map(int, input().split())) for i in range(n)]
	row_same = defaultdict(list)
	col_same = defaultdict(list)
	uf = DSU(n)
	for i in range(n):
		(row, col, time) = mines[i]
		row_same[row].append((col, i))
		col_same[col].append((row, i))
	for (k, v) in row_same.items():
		v.sort(key=lambda x: x[0])
		for i in range(len(v) - 1):
			if abs(v[i + 1][0] - v[i][0]) <= K:
				uf.merge(v[i + 1][1], v[i][1])
	for (k, v) in col_same.items():
		v.sort(key=lambda x: x[0])
		for i in range(len(v) - 1):
			if abs(v[i + 1][0] - v[i][0]) <= K:
				uf.merge(v[i + 1][1], v[i][1])
	exploding_time = []
	for g in uf.groups():
		min_time = inf
		for i in g:
			min_time = min(min_time, mines[i][-1])
		exploding_time.append(min_time)
	exploding_time.sort()

	def possible(X: int) -> bool:
		if X < 0:
			return False
		tmp = exploding_time.copy()
		for _ in range(X + 1):
			if not tmp:
				return True
			tmp.pop()
		if not tmp:
			return True
		return tmp[-1] <= X
	ng = -1
	ok = 10 ** 9 + 10
	while ok - ng > 1:
		med = (ng + ok) // 2
		if possible(med):
			ok = med
		else:
			ng = med
	print(ok)

