def gcd(a, b):
	if a < b:
		c = b
		b = a
		a = c
	while b != 0:
		t = b
		b = a % b
		a = t
	return int(a)

def extendedEuclides(a, b):
	xx = y = 0
	yy = x = 1
	while b != 0:
		q = int(a / b)
		t = b
		b = a % b
		a = t
		t = xx
		xx = x - q * xx
		x = t
		t = yy
		yy = y - q * yy
		y = t
	return [a, x, y]

def chineseRemainder(x, y, a, b):
	[d, s, t] = extendedEuclides(x, y)
	if a % d != b % d:
		return [0, -1]
	return [int((s * b * x + t * a * y) % (x * y) / d), x * y / d]
