def merge(l, r, k):
	nonlocal a, c
	if l >= r or k % 2 != 0:
		return False
	if k == 0:
		for i in range(l, r):
			a[i] = c
			c += 1
		return True
	k -= 2
	m = (l + r) // 2
	if k // 2 % 2 == 0:
		if merge(m, r, k // 2):
			return merge(l, m, k // 2)
		else:
			return False
	elif merge(m, r, k // 2 + 1):
		return merge(l, m, k // 2 - 1)
	else:
		return False
