		return
	res = 1 << 64
	for d in simple_div(sa):
		tmp = 0
		m = 0
		half = d >> 1
		for x in a:
			m = (x + m) % d
			tmp += m if m <= half else d - m
			if res <= tmp:
				break
		else:
			res = tmp
	print(res)
