def bfs(nodes, src):
	from collections import deque
	N = len(nodes)
	que = deque([(src, 0)])
	dist = [INF] * N
	dist[src] = 0
	while que:
		(u, c) = que.popleft()
		for v in nodes[u]:
			if dist[v] != INF:
				continue
			dist[v] = c + 1
			que.append((v, c + 1))
	return dist
