import bisect

def lowbit(x):
	return x & -x

def add(i, x):
	while i <= n:
		bit[i].append(x)
		i += lowbit(i)

def query(i, x):
	s = 0
	while i > 0:
		pos = bisect.bisect_left(bit[i], x)
		s += len(bit[i]) - pos
		i -= lowbit(i)
	return s
