def gcd(a, b):
	while b:
		(a, b) = (b, a % b)
	return a

def point(a, b, c, d):
	g = gcd(c - a, d - b)
	K = [(c - a) // g, (d - b) // g]
	if K == [0, 1]:
		SET.add(tuple(K + [a]))
	else:
		SET.add(tuple(K + [((d - b) * -a + (c - a) * b) / (c - a)]))
