	return L[1] >= k

def solve(n, k, A):
	if k not in A:
		return 'no'
	l = len(A)
	if l == 1:
		return 'yes'
	if l == 2:
		if min(A) == k:
			return 'yes'
		return 'no'
	for i in range(l - 2):
