def ipn():
	return int(input())

def main():
	for _ in range(ipn()):
		n = ipn()
		a = list_get()
		v = []
		heapq.heapify(v)
		dic = {}
		val = 0
		for i in range(n):
			if a[i] == 0:
				continue
			heapq.heappush(v, [-1 * a[i], i + 1])
			dic[i + 1] = a[i]
			val += 1
		out = []
		while val > 1:
			x = heapq.heappop(v)
			x[0] += 1
			e = v.pop()
			y = e[1]
			out.append([x[1], y])
			dic[y] -= 1
			if dic[y] == 0:
				dic.pop(y)
				val -= 1
			dic[x[1]] -= 1
			if dic[x[1]] == 0:
				dic.pop(x[1])
				val -= 1
			e[0] += 1
			if x[0] < 0:
				heapq.heappush(v, x)
			if e[0] < 0:
				heapq.heappush(v, e)
		output(len(out))
		if len(out) > 0:
			for i in out:
				print(*i)
	return
