class MaxHeapTransform(int):

	def __lt__(self, other):
		return self >= other
from heapq import *

def main():
	(n, k1, k2) = mpint()
	aa = list(mpint())
	bb = list(mpint())
	hp = [(MaxHeapTransform(abs(aa[i] - bb[i])), i) for i in range(n)]
	heapify(hp)
	for _ in range(k1):
		mx = heappop(hp)
		(num, i) = mx
		num = MaxHeapTransform(abs(num - 1))
		if aa[i] < bb[i]:
			aa[i] += 1
		else:
			aa[i] -= 1
		heappush(hp, (num, i))
	hp = [(MaxHeapTransform(abs(aa[i] - bb[i])), i) for i in range(n)]
	heapify(hp)
	for _ in range(k2):
		mx = heappop(hp)
		(num, i) = mx
		num = MaxHeapTransform(abs(num - 1))
		if bb[i] < aa[i]:
			bb[i] += 1
		else:
			bb[i] -= 1
		heappush(hp, (num, i))
	print(sum(((a - b) ** 2 for (a, b) in zip(aa, bb))))
