	s = None
	i = 0
	while i < n:
		j = i + 1
		v = b[i][0]
		while j < n and b[j][0] == v:
			j += 1
		if s is None:
			for z in range(i, j):
				c[z] = j - z - 1
			ans = n - j
		else:
			k = s
			while k < e and b[k][1] < b[i][1]:
				k += 1
			for z in range(i, j - 1):
				c[z] = j - z - 1 + e
			if k == e:
				c[j - 1] = c[e - 1]
			else:
				c[j - 1] = s + e - k
			v = n - i - j
			for z in range(i, j):
				while k < e and b[k][1] < b[z][1]:
					k += 1
				ans = min(ans, z + (e if k == s else c[k - 1]) + v)
		(s, e, i) = (i, j, j)
	print(ans)
