class DSU:
	maxi = 1
	node = -1

	def __init__(self, n):
		self.c = [-1] * n

	def same(self, x, y):
		return self.find(x) == self.find(y)

	def find(self, x):
		if self.c[x] < 0:
			return x
		self.c[x] = self.find(self.c[x])
		return self.c[x]

	def union(self, u, v):
		(u, v) = (self.find(u), self.find(v))
		if u == v:
			return False
		if self.c[u] > self.c[v]:
			(u, v) = (v, u)
		self.c[u] += self.c[v]
		self.c[v] = u
		if self.maxi <= -self.c[self.find(u)]:
			self.maxi = max(self.maxi, -self.c[self.find(u)])
			self.node = self.find(u)
		return True

	def size(self, x):
		return -self.c[self.find(x)]
