	def find(a):
		if a != p[a]:
			p[a] = find(p[a])
		return p[a]

	def union(a, b):
		(a, b) = (find(a), find(b))
		if a == b:
			return
		if size[a] > size[b]:
			(a, b) = (b, a)
		p[a] = b
		size[b] += size[a]
		return
	p = [i for i in range(N)]
	size = [1] * N
	ans1 = 0
	best = 10 ** 18
	best_ind = -1
	i = 0
	for (s, x, y) in edges:
		if find(x) != find(y):
			union(x, y)
			ans1 += max(0, s - K)
			max_used = s
		diff = abs(s - K)
		if diff < best:
			best = diff
			best_ind = i
		i += 1
	if not ans1:
		ans1 += abs(K - max_used)
	ans2 = best
	i = 0
	p = [i for i in range(N)]
	size = [1] * N
	(s, x, y) = edges[best_ind]
	union(x, y)
	for (s, x, y) in edges:
