def positive_dist(x, n, k, last):
	cur = n - 1
	total = 0
	while cur >= 0 and x[cur] > 0:
		total += 2 * x[cur]
		cur -= k
	if last and x[-1] > 0:
		total -= x[-1]
	return total

def negative_dist(x, n, k, last):
	cur = 0
	total = 0
	while cur < n and x[cur] < 0:
		total -= 2 * x[cur]
		cur += k
	if last and x[0] < 0:
		total += x[0]
	return total
