index_to_rank = [0] * n

def traverse():
	visited = [False] * n
	stack = [(0, None)]
	while stack:
		(i, parent) = stack[-1]
		if visited[i]:
			stack.pop()
			if parent is not None:
				size[parent] += size[i]
		else:
			visited[i] = True
			index_to_rank[i] = len(dfs)
			dfs.append(i)
			for j in reversed(children[i]):
				stack.append((j, i))
