	for i in range(n):
		s = s + a[i] if i <= c - 1 else s + a[i] - a[i - c]
		heappush(h, (a[i], i))
		if i <= c - 2:
			b[i] = s
		else:
			while i - h[0][1] >= c:
				heappop(h)
			v1 = b[i - c] + s - h[0][0]
			v2 = a[i] + b[i - 1]
