def root(x, level=200):
	dp = []
	while disjointSet[x] >= 0:
		dp.append(x)
		x = disjointSet[x]
	for i in dp:
		disjointSet[i] = x
	return x

def join(x, y):
	(r1, r2) = (root(x), root(y))
	if r1 == r2:
		return
	disjointSet[r2] = r1
