def main():
	(n, m) = map(int, input().split())
	g = [[] for _ in range(n)]
	for r in range(n):
		g[r] = list(map(int, input().split()))
	cols = [0 for _ in range(m)]
	rows = [0 for _ in range(n)]

	def prefZeros(vec):
		f = False
		for val in vec:
			if val == 1:
				if not f:
					f = True
			elif f:
				return False
		return True

	def prefOnes(vec):
		f = False
		for val in vec:
			if val == 0:
				if not f:
					f = True
			elif f:
				return False
		return True

	def case1():
		for i in range(m):
			cols[i] = 0
		for i in range(n):
			rows[i] = 0
		for i in range(m):
			if g[0][i] == 1:
				cols[i] = 1
		flip = False
		for r in range(1, n):
			row = [g[r][c] ^ cols[c] for c in range(m)]
			s = sum(row)
			is_pref_zeros = prefZeros(row)
			is_pref_ones = prefOnes(row)
			if s == 0:
				if flip:
					rows[r] = 1
			elif s == m:
				if not flip:
					rows[r] = 1
			elif is_pref_zeros:
				if not flip:
					flip = True
				else:
					rows[r] = 1
			elif is_pref_ones:
				rows[r] = 1
				if not flip:
					flip = True
				else:
					return False
			else:
				return False
		return True

	def case2():
		for i in range(m):
			cols[i] = 0
		for i in range(n):
			rows[i] = 0
		for i in range(m):
			if g[n - 1][i] == 0:
				cols[i] = 1
		flip = False
		for r in range(n - 1):
			row = [g[r][c] ^ cols[c] for c in range(m)]
			s = sum(row)
			is_pref_zeros = prefZeros(row)
			is_pref_ones = prefOnes(row)
			if s == 0:
				if flip:
					rows[r] = 1
			elif s == m:
				if not flip:
					rows[r] = 1
			elif is_pref_zeros:
				if not flip:
					flip = True
				else:
					rows[r] = 1
			elif is_pref_ones:
				rows[r] = 1
				if not flip:
					flip = True
				else:
					return False
			else:
				return False
		return True
	if case1() or case2():
		print('YES')
		print(''.join((str(r) for r in rows)))
		print(''.join((str(c) for c in cols)))
	else:
		print('NO')
main()

