import sys
(spies, turns, note, final) = map(int, input().split())
if note < final:
	next = 1
else:
	next = -1
answer = []

def pass_note(current_turn, next_watch, left, right, note):
	if current_turn == next_watch:
		if note in range(left, right + 1) or note + next in range(left, right + 1):
			return (note, 'X')
	if note < final:
		note += next
		return (note, 'R')
	else:
		note += next
		return (note, 'L')
current_turn = 0
for turn in range(turns):
	(next_watch, left, right) = map(int, input().split())
	while current_turn < next_watch:
		current_turn += 1
		(note, ans) = pass_note(current_turn, next_watch, left, right, note)
		answer.append(ans)
		if note == final:
			print(''.join(answer))
			sys.exit()
while note != final:
	current_turn += 1
	(note, ans) = pass_note(current_turn, 0, -1, -1, note)
	answer.append(ans)
print(''.join(answer))

import os
import sys
from io import BytesIO, IOBase
BUFSIZE = 8192

class FastIO(IOBase):
	newlines = 0

	def __init__(self, file):
		self._fd = file.fileno()
		self.buffer = BytesIO()
		self.writable = 'x' in file.mode or 'r' not in file.mode
		self.write = self.buffer.write if self.writable else None

	def read(self):
		while True:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			if not b:
				break
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines = 0
		return self.buffer.read()

	def readline(self):
		while self.newlines == 0:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			self.newlines = b.count(b'\n') + (not b)
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines -= 1
		return self.buffer.readline()

	def flush(self):
		if self.writable:
			os.write(self._fd, self.buffer.getvalue())
			(self.buffer.truncate(0), self.buffer.seek(0))

class IOWrapper(IOBase):

	def __init__(self, file):
		self.buffer = FastIO(file)
		self.flush = self.buffer.flush
		self.writable = self.buffer.writable
		self.write = lambda s: self.buffer.write(s.encode('ascii'))
		self.read = lambda : self.buffer.read().decode('ascii')
		self.readline = lambda : self.buffer.readline().decode('ascii')
(sys.stdin, sys.stdout) = (IOWrapper(sys.stdin), IOWrapper(sys.stdout))
