class hstr:

	def __init__(self, s):
		self.h = [0]
		self.pq = [1]
		self.h0 = [0]
		self.pq0 = [1]
		n = len(s)
		for i in range(n):
			self.h += [(self.h[i] * p + ord(s[i])) % q]
			self.pq += [self.pq[i] * p % q]
			self.h0 += [(self.h0[i] * p0 + ord(s[i])) % q0]
			self.pq0 += [self.pq0[i] * p0 % q0]

	def get(self, l, r):
		return ((self.h[r] - self.h[l] * self.pq[r - l]) % q + q) % q

	def get0(self, l, r):
		return ((self.h0[r] - self.h0[l] * self.pq0[r - l]) % q0 + q0) % q0
