def rec(li, k):
	if not li or k < 0:
		return 0
	(li1, li2) = ([], [])
	for a in li:
		if a & 1 << k:
			li1.append(a)
		else:
			li2.append(a)
	if not li1 or not li2:
		return rec(li, k - 1)
	return min(rec(li1, k - 1), rec(li2, k - 1)) + (1 << k)
