	f[i] = 1
	for j in range(i - 1, -1, -1):
		f[j] = f[j + 1]
		if j + 1 < i:
			f[j] += f[j + 2]
			if f[j] >= MOD:
				f[j] -= MOD
			if j + 2 < i:
				f[j] += f[j + 3]
				if f[j] >= MOD:
