		y = (x + i) % 10
		if y >= x:
			n -= d * 9 + y
		else:
			n -= 1 + y
		if n < 0:
			return -1
	if n % (k + 1) != 0:
		return -1
	p = int(n / (k + 1))
	if p >= 8:
