def gcd(a, b):
	if b == 0:
		return a
	return gcd(b, a % b)

def ext(a, b):
	if b == 0:
		return (1, 0)
	else:
		(y, x) = ext(b, a % b)
		y = y - a // b * x
		return (x, y)
