import sys
mod = 998244353

def mult(a, b):
	y = 1
	for i in range(b):
		y = y * a % mod
	return y

def getS(cnt, k, b1, b2):
	if b1 < b2:
		(b1, b2) = (b2, b1)
	if b1 == b2 == 0:
		s = mult(k - 1, cnt - 1)
		s = s * k % mod
		return s
	if b2 == 0:
		return mult(k - 1, cnt)
	re = [k - 1] * cnt
	for i in range(1, cnt):
		re[i] = re[i - 1] * (k - 1) % mod
	re[0] = k - (1 if b1 == b2 else 2)
	tot = 0
	mm = 1
	for i in range(cnt - 1, -1, -1):
		tot += mm * re[i]
		mm *= -1
		tot = (tot + mod) % mod
	return tot

def solve(x, k):
	n = len(x)
	x = [0] + x + [0]
	st = -1
	rt = 1
	for i in range(n + 2):
		if x[i] != -1:
			if st != -1:
				rt = rt * getS(i - st, k, x[st - 1], x[i]) % mod
			st = -1
		elif st == -1:
			st = i
	return rt
