def anp(x, y):
	vd = [1, x] + ([] if x % 2 else [2, x // 2])
	for i in range(3, int(x ** 0.5) + 1):
		if x % i == 0:
			vd.append(i)
			if i != x // i:
				vd.append(x // i)
	vd.sort()
	an = 2 * x + 2 * y + 2
	for i in range(len(dv)):
		cr = dv[i]
		p = bi.bisect(vd, cr)
		p -= 1
		if (x + y) // cr >= x // vd[p]:
			an = min(an, 2 * (cr + (x + y) // cr))
	return an
