from collections import deque

def cycle_detectable_topological_sort(g, ind):
	V = len(g)
	order = []
	depth = [-1] * V
	for i in range(V):
		if not ind[i]:
			order.append(i)
			depth[i] = 0
	q = deque(order)
	while q:
		v = q.popleft()
		cur_depth = depth[v]
		for u in g[v]:
			ind[u] -= 1
			if not ind[u]:
				depth[u] = max(depth[u], cur_depth + 1)
				q.append(u)
				order.append(u)
	if len(order) == V:
		return (order, depth)
	else:
		return (None, None)
