		seqSum = (i + 1) * (i // 2) // 2
	else:
		mid2 = mid
		seqSum = i * (i // 2) // 2
	leftSum = sum(ps, mid)
	rightSum = totalSum - sum(ps, mid2)
	print(rightSum - leftSum - seqSum + invSum, end=' ')

def minimize(m):
	ad = [m[0][0] * m[3][0], m[0][0] * m[3][1] + m[0][1] * m[3][0], m[0][1] * m[3][1]]
	bc = [m[1][0] * m[2][0], m[1][0] * m[2][1] + m[1][1] * m[2][0], m[1][1] * m[2][1]]
	det = [ad[0] - bc[0], ad[1] - bc[1], ad[2] - bc[2]]
	if det[0] != 0:
		disc = det[1] ** 2 - 4 * det[0] * det[2]
		if disc < 0:
			return []
		return [(-det[1] + disc ** 0.5) / (2 * det[0]), (-det[1] - disc ** 0.5) / (2 * det[0])]
	if det[1] != 0:
		return [-det[2] / det[1]]
	if det[2] != 0:
		return []
	return [0]

