def prime_list(n):
	sieve = [True] * n
	for i in range(3, int(n ** 0.5) + 1, 2):
		if sieve[i]:
			sieve[i * i::2 * i] = [False] * ((n - i * i - 1) // (2 * i) + 1)
	return [2] + [i for i in range(3, n, 2) if sieve[i]]

def prime_factors(n):
	if not hasattr(prime_factors, 'primes') or prime_factors.primes[-1] ** 2 < n:
		prime_factors.primes = prime_list(max(5000, int(n ** 0.5) + 1))
	res = []
	for p in prime_factors.primes:
		if p * p > n:
			break
		count = 0
		while n % p == 0:
			n //= p
			count += 1
		if count:
			res.append((p, count))
		if n == 1:
			break
	if n != 1:
		res.append((n, 1))
	return res

def update_available(n, available):
	pf = prime_factors(n)
	for (p, _) in pf:
		if available[p]:
			available[p::p] = [False] * ((len(available) - 1) // p)

def main():
