			b.append(a_num)
			update_available(a_num, available)
		else:
			b_num = available.index(True, a_num)
			b.append(b_num)
			update_available(b_num, available)
			break
	b_num = 2
	while len(b) < n:
		b_num = available.index(True, b_num)
		b.append(b_num)
		update_available(b_num, available)
	print(' '.join((str(x) for x in b)))
