				print('YES')
				print(*[i + 1 if k % 2 else j + 1 for k in range(m + 1)])
				return
	if m & 1:
		print('YES')
		print(*[1 if k % 2 else 2 for k in range(m + 1)])
		return
	for i in range(1, n):
		for j in range(n):
			if i != j:
				if a[0][i] == a[i][j]:
					print('YES')
					b = [1, i + 1, j + 1, i + 1]
					if not m % 4:
