def count(k, i, counts, color=None):
	if i in counts:
		return None
	m = 10 ** 9 + 7
	if 2 * i not in counts and 2 * i + 1 not in counts:
		layer = len(bin(i)) - 2
		if color is None:
			counts[i] = [l[k - layer]] * 6
		else:
			counts[i] = [0] * 6
			counts[i][color] = l[k - layer]
	elif 2 * i in counts and 2 * i + 1 in counts:
		left = counts[2 * i]
		right = counts[2 * i + 1]
		new = [0] * 6
		for _ in range(6):
			totleft = sum(left) - left[_] - left[(_ + 3) % 6]
			totright = sum(right) - right[_] - right[(_ + 3) % 6]
			if color is None or _ == color:
				new[_] = totleft * totright % m
		counts[i] = new
	else:
		layer = len(bin(i)) - 2
		if 2 * i in counts:
			left = counts[2 * i]
			right = [l[k - layer - 1]] * 6
		else:
			left = counts[2 * i + 1]
			right = [l[k - layer - 1]] * 6
		new = [0] * 6
		for _ in range(6):
			totleft = sum(left) - left[_] - left[(_ + 3) % 6]
