def a(n, bits, dp):
	if bits == 0:
		return 1
	if n == '0' or n == '':
		return 0
	if bits > len(n):
		return 0
	if bits == len(n):
		if n == '1' * len(n):
			return 1
		else:
			return 0
	ans = 0
	while bits != 0 and (n != '' and n != '0') and (bits < len(n)):
		ans += dp[len(n) - 1][bits]
		i = 1
		while i < len(n) and n[i] == '0':
			i += 1
		n = n[i:]
		bits -= 1
	if bits == 0:
		ans += 1
	elif bits == len(n) and n == '1' * len(n):
		ans += 1
	return ans
